{"content":"import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('NewsListPage', () {
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    const cachedItems = [
      NewsModel(title: 'Кэш новость 1', link: 'https://example.com/cached-1', date: DateTime.now()),
      NewsModel(title: 'Кэш новость 2', link: 'https://example.com/cached-2', date: DateTime.now()),
    ];

    const freshItems = [
      NewsModel(title: 'Сетевая новость 1', link: 'https://example.com/fresh-1', date: DateTime.now()),
      NewsModel(title: 'Сетевая новость 2', link: 'https://example.com/fresh-2', date: DateTime.now()),
    ];

    setUp(() {
      when(mockNewsRepository.loadCachedNewsFeed()).thenAnswer((_) async => cachedItems);
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => freshItems);
      when(mockNewsRepository.saveNewsList(any)).thenAnswer((_) async {});
    });

    testWidgets('should display cached items immediately while network request is in progress', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        ),
      );

      // Кэш показан мгновенно.
      expect(find.text('Кэш новость 1'), findsOneWidget);
      expect(find.text('Кэш новость 2'), findsOneWidget);
      // Сетевые новости ещё не пришли.
      expect(find.text('Сетевая новость 1'), findsNothing);

      // Индикатор загрузки присутствует.
      expect(find.byType(CircularProgressIndicator), findsOneWidget);

      await tester.pumpAndSettle();

      // После ответа сети данные обновлены.
      expect(find.text('Кэш новость 1'), findsNothing);
      expect(find.text('Сетевая новость 1'), findsOneWidget);
      expect(find.text('Сетевая новость 2'), findsOneWidget);
      // Индикатор загрузки исчез.
      expect(find.byType(CircularProgressIndicator), findsNothing);
    });

    testWidgets('should display fresh items when network returns data', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Сетевая новость 1'), findsOneWidget);
      expect(find.text('Сетевая новость 2'), findsOneWidget);
    });
  });
}
