6: class NewsListPage extends StatefulWidget {
7:   const NewsListPage({super.key});
8: 
9:   @override
10:   State<NewsListPage> createState() => _NewsListPageState();
11: }
12: 
13: class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
14:   static final _tween = Tween<double>(begin: 0.25, end: 1);
15: 
16:   late Future<List<NewsModel>> _newsListFuture;
17: 
18:   late final AnimationController _scaleController;
19:   late final Animation<double> _scaleAnimation;
20: 
21:   List<NewsModel> _cachedItems = const [];
22:   bool _isLoadingFromNetwork = false;
23: 
24:   @override
25:   void initState() {
26:     super.initState();
27:     _initAnimation();
28:     _loadCachedFirst();
29:   }
30: 
31:   @override
32:   void dispose() {
33:     _scaleController.dispose();
34:     super.dispose();
35:   }
36: 
37:   void _initAnimation() {
38:     _scaleController = AnimationController(
39:       vsync: this,
40:       duration: const Duration(milliseconds: 200),
41:     );
42:     _scaleAnimation = _tween.animate(_scaleController);
43:   }
44: 
45:   /// Cache-then-network паттерн: сначала показываем кэш, затем обновляем из сети.
46:   Future<void> _loadCachedFirst() async {
47:     final newsRepository = context.read<NewsRepository>();
48: 
49:     // 1️⃣ Мгновенно загружаем кэш из БД и отображаем его.
50:     setState(() {
51:       _cachedItems = [];
52:       _isLoadingFromNetwork = true;
53:     });
54: 
55:     List<NewsModel> cached;
56:     try {
57:       cached = await newsRepository.loadCachedNewsFeed();
58:     } catch (_) {
59:       // Кэш недоступен — ничего не показываем, перейдём к этапу сети.
60:       cached = const [];
61:     }
62: 
63:     if (!mounted) return;
64: 
65:     setState(() {
66:       _cachedItems = cached;
67:     });
68: 
69:     // 2️⃣ Параллельно запрашиваем свежие данные из сети.
70:     try {
71:       final freshItems = await newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
72:       if (!mounted) return;
73: 
74:       setState(() {
75:         _cachedItems = freshItems;
76:         _isLoadingFromNetwork = false;
77:         _scaleController.forward(); // запускаем анимацию появления
78:       });
79:     } catch (_) {
80:       if (!mounted) return;
81:       setState(() {
82:         _isLoadingFromNetwork = false;
83:       });
84:     }
85:   }
86: 
87:   @override
88:   Widget build(BuildContext context) {
89:     return Scaffold(
90:       appBar: AppBar(title: Text(context.loc.news)),
91:       body: ScaleTransition(
92:         scale: _scaleAnimation,
93:         child: ListView.builder(
94:           itemCount: _cachedItems.length + (_isLoadingFromNetwork ? 1 : 0),
