import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class NewsListPage extends StatefulWidget {
  const NewsListPage({super.key});

  @override
  State<NewsListPage> createState() => _NewsListPageState();
}

class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  List<NewsModel> _cachedItems = const [];
  bool _isLoadingFromNetwork = false;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _loadCachedFirst();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  // Cache-then-network паттерн: сначала показываем кэш, затем обновляем из сети.
  Future<void> _loadCachedFirst() async {
    final newsRepository = context.read<NewsRepository>();

    // Шаг 1 — сразу рисуем пустой список с индикатором загрузки (синхронная setState).
    setState(() {
      _cachedItems = [];
      _isLoadingFromNetwork = true;
    });

    // Шаг 2 — асинхронно грузим кэш и показываем его.
    List<NewsModel> cached;
    try {
      cached = await newsRepository.loadCachedNewsFeed();
    } catch (_) {
      cached = const [];
    }

    if (!mounted) return;

    setState(() {
      _cachedItems = cached;
    });

    // Шаг 3 — параллельно запрашиваем свежие данные из сети.
    try {
      final freshItems = await newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true));
      if (!mounted) return;

      setState(() {
        _cachedItems = freshItems;
        _isLoadingFromNetwork = false;
        _scaleController.forward(); // запускаем анимацию появления
      });
    } catch (_) {
      if (!mounted) return;
      setState(() {
        _isLoadingFromNetwork = false;
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: ScaleTransition(
        scale: _scaleAnimation,
        child: ListView.builder(
          itemCount: _cachedItems.length + (_isLoadingFromNetwork ? 1 : 0),
          itemBuilder: (BuildContext context, int index) {
            // Показываем индикатор загрузки пока идёт фоновый запрос.
            if (index == _cachedItems.length && _isLoadingFromNetwork) {
              return const Padding(
                padding: EdgeInsets.all(16),
                child: Center(child: CircularProgressIndicator()),
              );
            }

            final NewsModel news = _cachedItems[index];

            return Padding(
              key: ValueKey(news.link),
              padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
              child: NewsCard(model: news),
            );
          },
          padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
        ),
      ),
    );
  }
}

